<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import { longMonitorApi } from '@/api/longMonitor'
const router=useRouter(),rows=ref<any[]>([]),total=ref(0),loading=ref(false),q=reactive<any>({page:1,size:20,status:''}),data=(r:any)=>r.data.data
async function load(){loading.value=true;try{const d=data(await longMonitorApi.alarms(q));rows.value=d.items||[];total.value=d.total||0}finally{loading.value=false}}onMounted(load)
</script><template><div class="page"><div><h2>长效代理告警</h2><p>仅记录客户长效代理专项监控产生的异常、恢复和关闭状态。</p></div><el-card shadow="never"><div class="filters"><el-select v-model="q.status" placeholder="状态" clearable><el-option v-for="x in ['OPEN','RECOVERED','CLOSED']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="alarm_no" label="告警编号" width="190"/><el-table-column prop="customer_name" label="客户"/><el-table-column prop="service_no" label="服务"/><el-table-column prop="monitor_no" label="监控编号"/><el-table-column prop="status" label="状态"/><el-table-column prop="opened_at" label="发生时间" width="180"/><el-table-column prop="recovered_at" label="恢复时间" width="180"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="router.push(`/long-monitor/alarms/${s.row.id}`)">详情</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="q.page" v-model:page-size="q.size" :total="total" layout="total,sizes,prev,pager,next" @change="load"/></div></el-card></div></template><style scoped>.page{display:grid;gap:16px}h2{margin:0 0 6px}p{margin:0;color:#7b8494}.filters{display:flex;gap:10px;margin-bottom:14px}.pager{display:flex;justify-content:flex-end;margin-top:14px}</style>